// --- Brick bounce (ISSUES.md #1) -------------------------------------------

// Red tests for the missing brick bounce, one per case from the issue:
// per-face bounce, corner, push-out, neighbours (single bounce per pass) and
// tunnelling (swept detection).

test('brickHit: top face flips vy, keeps vx, pushes the ball out', () => {
  const brick = { x: 90, y: 100, w: 72, h: 20, alive: true };
  const ball = { x: 100, y: 100, r: 7, vx: 30, vy: 200, px: 100, py: 90 };
  const hit = brickHit(ball, [brick]);
  assert.equal(hit, brick);
  assert.equal(brick.alive, false);
  assert.ok(ball.vy < 0, 'vy should flip upward on a top hit');
  assert.equal(ball.vx, 30, 'vx must stay untouched on a top hit');
  assert.equal(collides(ball, brick), false, 'ball must be pushed out');
  assert.ok(ball.y + ball.r <= brick.y, 'ball ends above the brick');
});

test('brickHit: side face flips vx, keeps vy, pushes the ball out', () => {
  const brick = { x: 100, y: 90, w: 72, h: 20, alive: true };
  const ball = { x: 95, y: 100, r: 7, vx: 200, vy: 30, px: 92, py: 100 };
  const hit = brickHit(ball, [brick]);
  assert.equal(hit, brick);
  assert.equal(brick.alive, false);
  assert.ok(ball.vx < 0, 'vx should flip on a side hit');
  assert.equal(ball.vy, 30, 'vy must stay untouched on a side hit');
  assert.equal(collides(ball, brick), false, 'ball must be pushed out');
  assert.ok(ball.x + ball.r <= brick.x, 'ball ends left of the brick');
});

test('brickHit: corner hit flips both components', () => {
  const brick = { x: 100, y: 90, w: 72, h: 20, alive: true };
  // Equal penetration on both axes: the ball centre sits on the brick's
  // top-left diagonal.
  const ball = { x: 110, y: 100, r: 7, vx: 100, vy: -100, px: 110, py: 100 };
  const hit = brickHit(ball, [brick]);
  assert.equal(hit, brick);
  assert.equal(ball.vx, -100, 'vx flipped');
  assert.equal(ball.vy, 100, 'vy flipped');
  assert.equal(collides(ball, brick), false, 'ball must be pushed out');
});

test('brickHit: two bricks in the same pass => exactly one bounce', () => {
  const top = { x: 90, y: 90, w: 72, h: 20, alive: true };
  const bottom = { x: 90, y: 118, w: 72, h: 20, alive: true };
  // Deep in the seam: the ball overlaps BOTH bricks at the same time. A naive
  // per-brick bounce would flip vy twice and the ball would sail through.
  const ball = { x: 100, y: 114, r: 7, vx: 0, vy: 300, px: 100, py: 114 };
  brickHit(ball, [top, bottom]);
  assert.ok(ball.vy < 0, 'vy flipped exactly once (not double-flipped)');
  assert.equal(ball.vx, 0, 'vx untouched');
  assert.equal(collides(ball, top), false, 'no overlap left with top brick');
  assert.equal(collides(ball, bottom), false, 'no overlap left with bottom brick');
});

test('brickHit: sweep catches a fast ball that would tunnel through', () => {
  const brick = { x: 90, y: 100, w: 72, h: 20, alive: true };
  // Worst case from ISSUES.md #1: level 6 speed over a 50 ms frame => 35.5 px
  // per step, more than the 34 px needed to cross a brick. The end position
  // alone is past the brick (no overlap): only a swept check detects the hit.
  const dy = ballSpeed(6) * 0.05;
  const ball = { x: 100, y: 82 + dy, r: 7, vx: 0, vy: ballSpeed(6), px: 100, py: 82 };
  const hit = brickHit(ball, [brick]);
  assert.equal(hit, brick);
  assert.equal(brick.alive, false);
  assert.ok(ball.vy < 0, 'swept bounce flips vy');
  assert.ok(ball.y + ball.r <= brick.y, 'ball pushed back above the brick');
});

// Small local helper: place the ball below the field without importing the
// height (coverage intentionally light).
function belowField() {
  return 500;
}

