// --- Rendering (DOM) -------------------------------------------------------

// Main render loop. Brick collision is pure logic (`brickHit`); the loop only
// draws — and applies the score/combo side effects of the brick that was hit.
export function frame(ctx, state) {
  // Background
  ctx.fillStyle = palette.background;
  ctx.fillRect(0, 0, WIDTH, HEIGHT);

  // Brick collision: swept detection, one bounce per frame (see `brickHit`).
  const hit = brickHit(state.ball, state.bricks);
  if (hit) {
    state.combo += 1;
    state.score += scoreForBrick(hit, state.combo);
  }

  // Bricks: drawing only.
  for (const brick of state.bricks) {
    if (!brick.alive) continue;
    ctx.fillStyle = brickColor(brick.row);
    ctx.fillRect(brick.x, brick.y, brick.w, brick.h);
  }

